def is_beautiful(arr):
    n = len(arr)
    for i in range(n):
        for k in range(i + 1, n):
            for j in range(k + 1, n):                    # check every triple directly
                if arr[k] * 2 == arr[i] + arr[j]:
                    return False
    return True

# Conceptually: try permutations of 1..n (e.g., via backtracking) until
# is_beautiful() returns True. Correct, but the number of permutations
# grows factorially, making this infeasible beyond very small n.

