def beautiful_array(n):
    memo = {}

    def build(N):
        if N in memo:
            return memo[N]
        if N == 1:
            memo[1] = [1]
            return [1]
        left = [2 * x - 1 for x in build((N + 1) // 2)]    # map to all odd values
        right = [2 * x for x in build(N // 2)]              # map to all even values
        result = left + right
        memo[N] = result
        return result

    return build(n)

