import java.util.*;

public class Main {
    static Map<Integer, List<Integer>> memo = new HashMap<>();

    static List<Integer> beautifulArray(int n) {
        if (memo.containsKey(n)) return memo.get(n);
        if (n == 1) {
            List<Integer> base = new ArrayList<>();
            base.add(1);
            memo.put(1, base);
            return base;
        }
        List<Integer> left = new ArrayList<>();
        for (int x : beautifulArray((n + 1) / 2)) left.add(2 * x - 1);    // map to odd values
        List<Integer> right = new ArrayList<>();
        for (int x : beautifulArray(n / 2)) right.add(2 * x);              // map to even values
        List<Integer> result = new ArrayList<>(left);
        result.addAll(right);
        memo.put(n, result);
        return result;
    }
}

