#include <bits/stdc++.h>
using namespace std;

unordered_map<int, vector<int>> memo;

vector<int> beautifulArray(int n) {
    if (memo.count(n)) return memo[n];
    if (n == 1) { memo[1] = {1}; return memo[1]; }
    vector<int> left, right;
    for (int x : beautifulArray((n + 1) / 2)) left.push_back(2 * x - 1);   // map to odd values
    for (int x : beautifulArray(n / 2)) right.push_back(2 * x);             // map to even values
    vector<int> result = left;
    result.insert(result.end(), right.begin(), right.end());
    memo[n] = result;
    return result;
}
